#!/usr/bin/env bash
# ============================================================================
#  GSZ step108 — wire the coupon engine into checkout + make the promo-bar
#  chip driven by the featured discount code (fully dashboard-controlled).
#  Safe + idempotent: backs up, patches via anchored node edits, validates,
#  migrates, restarts. Any failure restores the previous files automatically.
# ============================================================================
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step108-$TS"
FILES=(server.js routes/checkout.js views/partials/store_top.ejs views/checkout.ejs)
TMP=$(mktemp -d)

echo "==> step108: coupon checkout + dynamic promo bar"
mkdir -p "$BK"
for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"

restore() {
  echo "!!  FAILED — restoring previous files from backup"
  for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  pm2 restart gsz >/dev/null 2>&1 || true
  echo "!!  restored. no changes kept."
}
trap 'restore' ERR

# ---- decode embedded node scripts ----
echo "" | base64 -d > "$TMP/patch_step108.js"
echo ""   | base64 -d > "$TMP/migrate_step108.js"

# ---- apply anchored patches ----
echo "==> applying patches"
node "$TMP/patch_step108.js" "$GSZ"

# ---- validate ----
echo "==> validating"
node --check "$GSZ/server.js"
node --check "$GSZ/routes/checkout.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');['views/partials/store_top.ejs','views/checkout.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"

# ---- migrate ----
echo "==> migrating db"
( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/migrate_step108.js" )

# ---- restart ----
echo "==> restarting app"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
sleep 2

# ---- health ----
echo "==> health checks"
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
[ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage returned $CODE"; false; }

HP=$(curl -s http://127.0.0.1:3900/ || true)
grep -q 'code-chip' <<<"$HP" && echo "    promo chip renders: OK" || echo "    promo chip: not shown (no featured code?) — non-fatal"

VR=$(curl -s 'http://127.0.0.1:3900/api/coupon/validate?code=__nope__&p=__none__&region=PK' || true)
grep -q '"ok":false' <<<"$VR" && echo "    validate endpoint live: OK" || { echo "    validate endpoint FAILED: $VR"; false; }

SLUG=$(cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node -e "require('dotenv/config');const{Pool}=require('pg');const p=new Pool({host:process.env.DB_HOST||'127.0.0.1',port:+(process.env.DB_PORT||5432),user:process.env.DB_USER,password:process.env.DB_PASSWORD,database:process.env.DB_NAME});p.query(\"SELECT slug FROM products WHERE active AND NOT hidden ORDER BY id LIMIT 1\").then(function(r){console.log(r.rows[0]?r.rows[0].slug:'');return p.end();}).catch(function(){console.log('')})" 2>/dev/null || true)
if [ -n "$SLUG" ]; then
  DV=$(curl -s "http://127.0.0.1:3900/api/coupon/validate?ctx=single&region=PK&code=GALAXY10&p=$SLUG" || true)
  if grep -q '"ok":true' <<<"$DV"; then echo "    GALAXY10 applies on '$SLUG': OK"; else echo "    GALAXY10 check on '$SLUG': $DV (non-fatal — code may be off/limited)"; fi
fi

trap - ERR
rm -rf "$TMP"
echo ""
echo "==> step108 OK ✅"
echo "    • Checkout now has a Discount code field (live-applies to total + each payment amount)."
echo "    • Top promo bar chip is driven by your FEATURED code in /admin/coupons (feature a code = shows, unfeature = hides)."
echo "    • Orders store the code used + discount; each use increments the code's Used count."
